import{_ as n}from"./chunks/dashboard.dWD4oxS0.js";import{_ as o,C as s,o as e,c as i,a2 as a,b as d,w as l,a as g,E as h,a3 as f}from"./chunks/framework.BODD28Fk.js";const b=JSON.parse('{"title":"IBS 워크스페이스 소개","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1793461578000}'),E={name:"index.md"};function m(c,t,B,C,A,p){const r=s("Mermaid");return e(),i("div",null,[t[1]||(t[1]=a('<h1 id="ibs-워크스페이스-소개" tabindex="-1">IBS 워크스페이스 소개 <a class="header-anchor" href="#ibs-워크스페이스-소개" aria-label="Permalink to &quot;IBS 워크스페이스 소개&quot;">​</a></h1><blockquote><p>**IBS (Intelligent Business System)**는 부동산 개발사업의 전 과정 (토지 매입부터 인허가, 분양 계약, 대금 수납, 회계 정산, 소송 관리까지)에서 발생하는 핵심 데이터와 일상적인 업무를 하나로 통합하여 협업하는 <strong>디벨로퍼 전용 지능형 업무 플랫폼</strong>입니다.</p></blockquote><p>모든 부서의 업무 (할 일), 회의 결정 사항, 전자결재 품의 이력 및 현장 실사 데이터가 유기적으로 연결되어, 개인의 경험에 의존하던 노하우를 조직의 영구적인 지식 자산으로 축적합니다.</p><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+n+'" alt="IBS 메인 대시보드 화면"></p></div><h2 id="🚀-신입사원을-위한-직무별-빠른-시작-quick-guide" tabindex="-1">🚀 신입사원을 위한 직무별 빠른 시작 (Quick Guide) <a class="header-anchor" href="#🚀-신입사원을-위한-직무별-빠른-시작-quick-guide" aria-label="Permalink to &quot;🚀 신입사원을 위한 직무별 빠른 시작 (Quick Guide)&quot;">​</a></h2><p>IBS에 처음 오셨다면, 본인의 직무와 소속 부서에 맞는 길잡이를 따라 시작해 보세요.</p><table tabindex="0"><thead><tr><th style="text-align:left;">직무 / 소속</th><th style="text-align:left;">신입사원 1일차 추천 경로</th><th style="text-align:left;">핵심 활용 메뉴</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>🏢 본사 / 경영지원</strong></td><td style="text-align:left;"><a href="/intro/getting-started.html">내 프로필 확인</a> → <a href="/hr-manage/organization.html">인사 정보 및 조직도 조회</a> → <a href="/approval/draft.html">첫 전자결재 품의 작성</a></td><td style="text-align:left;">전자결재 18종, 대외 공문 발송, 근태/연차</td></tr><tr><td style="text-align:left;"><strong>🏗️ 개발 / 사업관리</strong></td><td style="text-align:left;"><a href="/work-manage/workspace.html">워크스페이스 참여</a> → <a href="/work-manage/meeting.html">회의록 작성</a> → <a href="/work-manage/issue.html">첫 업무(할 일) 등록</a></td><td style="text-align:left;">워크스페이스, 회의록, 로드맵, 현장 사진 첨부</td></tr><tr><td style="text-align:left;"><strong>🤝 분양 / 영업 / CRM</strong></td><td style="text-align:left;"><a href="/project/">프로젝트 선택</a> → <a href="/contract/status.html">동·호수 배치 현황 확인</a> → <a href="/contract/">분양 계약 등록</a></td><td style="text-align:left;">동호배치도, 계약 등록/승계, 수수료 정산</td></tr><tr><td style="text-align:left;"><strong>💰 자금 / 수납 / 회계</strong></td><td style="text-align:left;"><a href="/intro/dashboard.html">대시보드 자금 확인</a> → <a href="/payment/">회차별 대금 수납 등록</a> → <a href="/ledger/status.html">입금 매칭</a></td><td style="text-align:left;">수납 관리, 고지서 출력, 회계 자금 출납</td></tr><tr><td style="text-align:left;"><strong>👔 임원 / 부서장</strong></td><td style="text-align:left;"><a href="/intro/getting-started.html">모바일 앱 설치 및 생체인증 등록</a> → <a href="/approval/action.html">결재 대기 문서 원터치 승인</a></td><td style="text-align:left;">대시보드 지표 모니터링, 전자결재 승인/전결</td></tr></tbody></table><h2 id="시스템-핵심-아키텍처" tabindex="-1">시스템 핵심 아키텍처 <a class="header-anchor" href="#시스템-핵심-아키텍처" aria-label="Permalink to &quot;시스템 핵심 아키텍처&quot;">​</a></h2><p>IBS는 흩어져 있는 업무 영역을 하나의 맥락으로 연결하여 데이터 무결성과 신속한 의사결정을 지원합니다.</p>',9)),(e(),d(f,null,{default:l(()=>[h(r,{id:"mermaid-100",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%5B%22%F0%9F%8F%97%EF%B8%8F%20%EB%B6%80%EB%8F%99%EC%82%B0%20%EA%B0%9C%EB%B0%9C%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%EB%B6%80%EC%A7%80%2F%EC%83%81%ED%92%88%20%EC%84%A4%EC%A0%95%22%5D%20--%3E%20B%5B%22%EB%B6%84%EC%96%91%20%EA%B3%84%EC%95%BD%20(CRM)%22%5D%0A%20%20%20%20%20%20%20%20B%20--%3E%20C%5B%22%EB%8C%80%EA%B8%88%20%EC%88%98%EB%82%A9%20%26%20%EA%B3%A0%EC%A7%80%22%5D%0A%20%20%20%20%20%20%20%20C%20--%3E%20D%5B%22%ED%9A%8C%EA%B3%84%20%EA%B2%B0%EC%82%B0%20%26%20%EC%98%88%EC%82%B0%20%ED%86%B5%EC%A0%9C%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20%ED%98%91%EC%97%85%EC%9D%98%EC%82%AC%EA%B2%B0%EC%A0%95%20%5B%22%F0%9F%A4%9D%20%EC%A0%84%EC%82%AC%20%ED%98%91%EC%97%85%20%26%20%EA%B2%BD%EC%98%81%20%EA%B4%80%EB%A6%AC%22%5D%0A%20%20%20%20%20%20%20%20E%5B%22%F0%9F%8E%AF%20%EC%97%85%EB%AC%B4%20(%ED%95%A0%20%EC%9D%BC%2F%EB%A1%9C%EB%93%9C%EB%A7%B5)%22%5D%20%3C--%3E%20F%5B%22%F0%9F%93%9D%20%ED%9A%8C%EC%9D%98%EB%A1%9D%20%26%20%EC%95%A1%EC%85%98%EC%95%84%EC%9D%B4%ED%85%9C%22%5D%0A%20%20%20%20%20%20%20%20F%20%3C--%3E%20G%5B%22%F0%9F%93%91%20%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%20%26%20%EC%A0%84%EA%B2%B0%22%5D%0A%20%20%20%20%20%20%20%20G%20%3C--%3E%20H%5B%22%E2%9C%89%EF%B8%8F%20%EB%8C%80%EC%99%B8%20%EA%B3%B5%EB%AC%B8%20%EA%B4%80%EB%A6%AC%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20D%20%3C--%3E%20G%0A%20%20%20%20A%20%3C--%3E%20E%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[g(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="왜-ibs-워크스페이스인가" tabindex="-1">왜 IBS 워크스페이스인가? <a class="header-anchor" href="#왜-ibs-워크스페이스인가" aria-label="Permalink to &quot;왜 IBS 워크스페이스인가?&quot;">​</a></h2><ul><li><strong>친숙하고 직관적인 업무 관리</strong> - 회의록에서 결정된 액션 아이템이 담당자의 업무 (Issue)로 원클릭 발행되어 생성부터 완료까지 투명하게 추적됩니다.</li><li><strong>도메인 결합형 원스톱 데이터 파이프라인</strong> - 부지, 상품, 계약, 수납, 회계가 단일 흐름으로 연결되어 엑셀 수기 관리 시 발생하는 오기와 누락을 원천 차단합니다.</li><li><strong>의사결정의 지식 자산화</strong> - 과거 회의 의제, 경영진의 전자결재 품의 승인 이력, 공문 발송 기록이 영구 보관되어 담당자가 바뀌어도 업무 히스토리가 완벽히 계승됩니다.</li><li><strong>현장과 본사의 실시간 동기화</strong> - 외근 및 공사 현장 실사 중 모바일로 촬영한 현장 사진과 이슈가 즉시 본사 PC 대시보드에 0.1초 내로 동기화됩니다.</li></ul><h2 id="멀티플랫폼-협업-환경-웹-모바일" tabindex="-1">멀티플랫폼 협업 환경 (웹 &amp; 모바일) <a class="header-anchor" href="#멀티플랫폼-협업-환경-웹-모바일" aria-label="Permalink to &quot;멀티플랫폼 협업 환경 (웹 &amp; 모바일)&quot;">​</a></h2><p>IBS 워크스페이스는 사무실 대화면 업무를 위한 **데스크톱 웹 (PC)**과 현장 점검 및 외근 이동성을 위한 **스마트폰 모바일 앱 (iOS / Android)**이 실시간으로 상호 연동됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">데스크톱 웹 (PC)</th><th style="text-align:left;">모바일 앱 (iOS / Android)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>주요 활용 환경</strong></td><td style="text-align:left;">사무실 PC, 대화면 모니터</td><td style="text-align:left;">외근, 출장, 현장 이동, 긴급 상황</td></tr><tr><td style="text-align:left;"><strong>핵심 목적</strong></td><td style="text-align:left;">심층 회계 정산, 대량 데이터 등록, 계약/수납 관리, PDF 인쇄</td><td style="text-align:left;">원터치 전자결재 승인, 현장 사진 첨부 및 이슈 처리, 실시간 소통</td></tr><tr><td style="text-align:left;"><strong>전자결재</strong></td><td style="text-align:left;">상세 품의 작성, 첨부파일 검토, 결재선/위임 관리, PDF 출력</td><td style="text-align:left;"><strong>생체인증(Face ID/지문) 원터치 승인</strong>, 긴급 상신 및 결재 알림</td></tr><tr><td style="text-align:left;"><strong>업무 및 회의</strong></td><td style="text-align:left;">로드맵 간트차트, 간트 일정 관리, 회의록 상세 작성</td><td style="text-align:left;"><strong>현장 사진 즉시 촬영·첨부</strong>, 진척도 슬라이더 갱신, 안건 확인</td></tr><tr><td style="text-align:left;"><strong>사내 메신저</strong></td><td style="text-align:left;">화면 우측 슬라이드 드로어 소통, 파일/미디어 서랍 열람</td><td style="text-align:left;"><strong>최상단 헤더 원터치 진입</strong>, <strong>실시간 푸시 알림</strong> 즉시 답장</td></tr><tr><td style="text-align:left;"><strong>특화 기능</strong></td><td style="text-align:left;">다중 창 분할 열람, 엑셀/PDF 대량 다운로드</td><td style="text-align:left;"><strong>스마트폰 외부 파일 공유 연동</strong>, 오프라인 네트워크 감지 배너</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 유기적인 데이터 동기화</p><p>웹 (PC)에서 작성한 전자결재나 회의 안건은 모바일 앱에 즉시 푸시 알림으로 전달되며, 모바일에서 현장 사진을 촬영하여 등록한 업무는 웹 화면에 실시간으로 즉시 반영됩니다.</p></div><h2 id="주요-기능-및-매뉴얼-안내" tabindex="-1">주요 기능 및 매뉴얼 안내 <a class="header-anchor" href="#주요-기능-및-매뉴얼-안내" aria-label="Permalink to &quot;주요 기능 및 매뉴얼 안내&quot;">​</a></h2><h3 id="🏢-1-본사-관리-시스템-hq-management" tabindex="-1">🏢 1. 본사 관리 시스템 (HQ Management) <a class="header-anchor" href="#🏢-1-본사-관리-시스템-hq-management" aria-label="Permalink to &quot;🏢 1. 본사 관리 시스템 (HQ Management)&quot;">​</a></h3><ul><li><strong><a href="/hr-manage/organization.html">인사 조직 관리</a></strong>: 부서 계층 트리, 직급/직위/직책, 전사 조직도, 직원 정보, 연차/근태 및 승진 심사</li><li><strong><a href="/approval/">전자결재 시스템</a></strong>: 18종 전용 양식 기안, 조직도 기반 자동 결재선 산출, 전결 규정, 결재 위임 및 전자직인 PDF 보관</li><li><strong><a href="/official-letter/">대외 공문 관리</a></strong>: 관공서/협력사 발송 공문 표준 A4 작성 (실시간 프리뷰), 수신 공문 접수 및 회신 공문 연계</li><li><strong><a href="/ledger/status.html">본사 회계 관리</a></strong>: 본사 법인 계좌 거래 내역, 본사 운영비 및 출납 결산 관리</li></ul><h3 id="🎯-2-업무-관리-및-협업-공간-workspace-collaboration" tabindex="-1">🎯 2. 업무 관리 및 협업 공간 (Workspace &amp; Collaboration) <a class="header-anchor" href="#🎯-2-업무-관리-및-협업-공간-workspace-collaboration" aria-label="Permalink to &quot;🎯 2. 업무 관리 및 협업 공간 (Workspace &amp; Collaboration)&quot;">​</a></h3><ul><li><strong><a href="/work-manage/workspace.html">워크스페이스 개요</a></strong>: 전사 부서 및 프로젝트 단위 통합 협업 공간 구성</li><li><strong><a href="/work-manage/meeting.html">회의록 관리</a></strong>: 회의 의제, 결정 사항, 후속 조치 (Action Item) 연동 자산화</li><li><strong><a href="/work-manage/issue.html">업무 (할 일) 및 로드맵</a></strong>: 담당자별 업무 할당, 진척률 관리, 마일스톤 로드맵 트래킹</li><li><strong><a href="/work-manage/calendar.html">캘린더 &amp; 사내 메신저</a></strong>: 마일스톤 일정 공유 및 실시간 1:1 / 프로젝트 공용 채널 소통</li></ul><h3 id="🏗️-3-프로젝트-관리-시스템-project-development" tabindex="-1">🏗️ 3. 프로젝트 관리 시스템 (Project Development) <a class="header-anchor" href="#🏗️-3-프로젝트-관리-시스템-project-development" aria-label="Permalink to &quot;🏗️ 3. 프로젝트 관리 시스템 (Project Development)&quot;">​</a></h3><ul><li><strong><a href="/project/">프로젝트 설정</a></strong>: 사업지 마스터 정보 등록, 동·호수 및 유닛 타입 배치, 분양 조건 및 사업 예산 편성</li><li><strong><a href="/project/site-manage.html">부지 정보 관리</a></strong>: 필지별 토지 조서, 소유자 상담 및 토지 매입 계약 관리</li><li><strong><a href="/contract/">분양 계약 관리</a></strong>: 수분양자 계약 등록, 옵션 계약, 동·호수 배치 현황 및 권리의무 승계·해약 관리</li><li><strong><a href="/sales/">분양 대행 관리</a></strong>: 직영/외주 분양 조직 구성, 계약 실적 매핑, 차수별 수수료 정책 및 정산·지급</li><li><strong><a href="/payment/">대금 수납 및 고객 고지</a></strong>: 회차별 납부 관리, 연체료 자동 산출, 맞춤형 수납 고지서 출력 및 SMS 발송</li><li><strong><a href="/project/budgets.html">프로젝트 회계 &amp; 자금</a></strong>: 사업비 집행 통제, 사업 수지 캐시플로우 및 예산 대비 실적 분석</li><li><strong><a href="/document/">문서 보관소 &amp; 소송 관리</a></strong>: 프로젝트 인허가 문서 영구 보관, 소송 사건 기일 및 판결 관리</li></ul><h2 id="시작하기-가이드" tabindex="-1">시작하기 가이드 <a class="header-anchor" href="#시작하기-가이드" aria-label="Permalink to &quot;시작하기 가이드&quot;">​</a></h2><p>처음 방문하셨다면 아래 가이드부터 순서대로 확인하시는 것을 추천합니다.</p><ul><li>💡 <strong><a href="/intro/getting-started.html">IBS 시작하기 가이드</a></strong>: 첫 로그인, 계정 온보딩, 1일차 5분 퀵스타트 체크리스트</li><li>📊 <strong><a href="/intro/dashboard.html">대시보드 사용 매뉴얼</a></strong>: 30초 조작법, 추천 핵심 위젯 TOP 5 및 개인 맞춤 레이아웃 설정</li><li>💬 <strong><a href="/work-manage/chat.html">사내 메신저 가이드</a></strong>: 실시간 채팅, 현장 사진/자료 공유, 모바일 푸시 알림 설정</li><li>✅ <strong><a href="/work-manage/todo.html">나의 할일 관리</a></strong>: 하루 업무 메모, 체크리스트 관리 및 공식 프로젝트 업무(Issue) 전환</li><li>🔍 <strong><a href="/work-manage/search.html">통합 검색 엔진</a></strong>: 전사 워크스페이스 회의록·업무·문서 통합 키워드 검색</li></ul>',16))])}const y=o(E,[["render",m]]);export{b as __pageData,y as default};
